# Manifest invariants. The jamovi definitions are generated by
# tools/generate_jamovi.R; these tests pin the properties that made the module
# misbehave before (ghost options, stale caches, unwired controls).

engine_source <- function() {
  files <- list.files(file.path(repo_root(), "R"), pattern = "^cna_.*\\.R$", full.names = TRUE)
  paste(unlist(lapply(files, readLines, warn = FALSE)), collapse = "\n")
}

test_that("the committed definitions are exactly what the generator writes", {
  root <- repo_root()
  tmp <- tempfile("cna-gen-")
  dir.create(tmp)
  on.exit(unlink(tmp, recursive = TRUE), add = TRUE)
  invisible(file.copy(file.path(root, c("DESCRIPTION", "tools", "jamovi", "R")), tmp,
                      recursive = TRUE))
  log <- system2(file.path(R.home("bin"), "Rscript"),
                 c(shQuote(file.path(tmp, "tools", "generate_jamovi.R")), shQuote(tmp)),
                 stdout = TRUE, stderr = TRUE)
  expect_null(attr(log, "status"))
  generated <- c(file.path("jamovi", paste0(rep(ANALYSES, each = 3), ".",
                                            c("a", "r", "u"), ".yaml")),
                 file.path("R", paste0(ANALYSES, ".b.R")))
  for (f in generated)
    expect_identical(readLines(file.path(tmp, f), warn = FALSE),
                     readLines(file.path(root, f), warn = FALSE),
                     label = paste(f, "differs from the generator output"))
  # jmvtools::prepare() re-folds the manifest's long strings: compare content
  expect_identical(yaml::read_yaml(file.path(tmp, "jamovi", "0000.yaml")),
                   yaml::read_yaml(file.path(root, "jamovi", "0000.yaml")))
})

test_that("the engine has no tna:: references", {
  expect_false(grepl("tna::", engine_source(), fixed = TRUE))
})

test_that("every option the engine reads is declared somewhere", {
  src <- engine_source()
  read <- unique(sub("^(o|options)\\$", "",
                     regmatches(src, gregexpr("\\b(o|options)\\$[A-Za-z0-9_]+", src))[[1]]))
  declared <- unique(unlist(lapply(ANALYSES, option_names)))
  expect_length(setdiff(read, declared), 0)
})

test_that("no ghost options: every declared option is used", {
  src <- engine_source()
  for (a in ANALYSES) {
    r_visible <- unlist(lapply(read_def(a, "r")$items, function(i) as.character(i$visible)))
    used_by_visibility <- unique(unlist(regmatches(r_visible,
                                                   gregexpr("[A-Za-z_][A-Za-z0-9_]*", r_visible))))
    measures <- paste0("centrality_", names(cna(".cna_measure_map")))   # read via paste0()
    unused <- Filter(function(o) !grepl(paste0("\\b", o, "\\b"), src) &&
                       !o %in% c("data", used_by_visibility, measures),
                     option_names(a))
    expect_identical(unused, character(), label = paste(a, "unused options"))
  }
})

test_that("clearWith names only declared options", {
  for (a in ANALYSES) {
    declared <- option_names(a)
    cw <- unique(unlist(lapply(read_def(a, "r")$items, `[[`, "clearWith")))
    expect_length(setdiff(cw, declared), 0)
  }
})

test_that("display options never invalidate a cached computation", {
  cosmetic <- function(o) grepl(paste0("^plot_|_table_|_max_rows$|_plot_style$|",
                                       "^compare_plot_type$|^cliques_max_plot$|_show_"), o)
  for (a in ANALYSES) {
    holders <- Filter(function(i) grepl("State$|^buildModelContent$", i$name),
                      read_def(a, "r")$items)
    expect_gt(length(holders), 3)
    for (h in holders) {
      bad <- Filter(cosmetic, h$clearWith)
      expect_identical(as.character(unlist(bad)), character(),
                       label = paste(a, h$name, "display options in clearWith"))
    }
  }
})

test_that("each output re-renders when its cached state changes", {
  # an image or table must clear whenever the state it draws from clears
  for (a in ANALYSES) {
    items <- read_def(a, "r")$items
    by_name <- stats::setNames(items, vapply(items, `[[`, "", "name"))
    holders <- names(by_name)[grepl("State$", names(by_name))]
    for (h in holders) {
      stem <- sub("State$", "", h)
      readers <- Filter(function(nm) startsWith(nm, stem) && nm != h &&
                          by_name[[nm]]$type %in% c("Table", "Image"), names(by_name))
      for (nm in readers)
        expect_true(all(by_name[[h]]$clearWith %in% by_name[[nm]]$clearWith),
                    label = paste(a, nm, "misses clearWith of", h))
    }
  }
})

test_that("every renderFun has a renderer and a backend method", {
  renderers <- names(cna(".cna_renderers"))
  for (a in ANALYSES) {
    items <- read_def(a, "r")$items
    funs <- unlist(lapply(items, `[[`, "renderFun"))
    names_with <- vapply(Filter(function(i) !is.null(i$renderFun), items), `[[`, "", "name")
    expect_true(all(names_with %in% renderers), label = paste(a, "renderers"))
    backend <- read_repo("R", paste0(a, ".b.R"))
    expect_true(all(vapply(funs, function(f) any(grepl(paste0(f, " = function"), backend, fixed = TRUE)),
                           logical(1))), label = paste(a, "backend methods"))
  }
})

test_that("every option has exactly one UI control", {
  controls <- function(node) {
    here <- if (!is.null(node$type) && node$type %in% c("CheckBox", "TextBox", "ComboBox",
                                                         "LevelSelector", "VariablesListBox",
                                                         "RadioButton"))
      node$optionName %||% node$name
    c(here, unlist(lapply(node$children, controls)))
  }
  for (a in ANALYSES) {
    bound <- unique(controls(list(children = read_def(a, "u")$children)))
    expect_setequal(bound, setdiff(option_names(a), "data"))
  }
})

test_that("the five analyses are registered in the module manifest", {
  manifest <- yaml::read_yaml(file.path(repo_root(), "jamovi", "0000.yaml"))
  expect_setequal(vapply(manifest$analyses, `[[`, "", "name"), ANALYSES)
  expect_equal(manifest$version, read.dcf(file.path(repo_root(), "DESCRIPTION"))[, "Version"][[1]])
  data_files <- vapply(manifest$datasets, `[[`, "", "path")
  expect_true(all(file.exists(file.path(repo_root(), "data", data_files))))
})

# --- no sequence analyses ---------------------------------------------------------
# Co-occurrence ignores order, so the module offers no sequence plots
# (index/heatmap, state distribution over time) and no subsequence comparison.

test_that("the module has no sequence analyses", {
  sequence_words <- "sequence|seqcompare|distribution_plot|buildModel_show_distribution"
  invisible(lapply(ANALYSES, \(a) {
    expect_identical(grep(sequence_words, option_names(a), value = TRUE), character(),
                     label = paste(a, "options"))
    res <- vapply(read_def(a, "r")$items, `[[`, "", "name")
    expect_identical(grep("sequence|seqcompare|distribution", res, value = TRUE), character(),
                     label = paste(a, "results"))
  }))
  expect_identical(grep("sequence|seqcompare|distribution", names(cna(".cna_renderers")),
                        value = TRUE), character())
  expect_false(grepl("sequence_plot|sequence_compare|distribution_plot", engine_source()))
})

# --- one panel layout ---------------------------------------------------------------

panel_nodes <- function(nodes)
  do.call(c, lapply(nodes, \(n) c(list(n), panel_nodes(n$children))))

check_box_labels <- function(a, box) {
  section_labels <- c("Output", "Settings", "Method", "Measures", "Network Plot Appearance",
                      "Groups", "Clusters", "Choosing k")
  labels <- vapply(Filter(\(n) identical(n$type, "Label"), panel_nodes(box$children)),
                   `[[`, "", "label")
  expect_true("Output" %in% labels, label = paste(a, box$label, "has an Output column"))
  expect_identical(setdiff(labels, section_labels), character(),
                   label = paste(a, box$label, "labels"))
}

test_that("every analysis panel has the same shape", {
  invisible(lapply(ANALYSES, \(a) {
    top <- read_def(a, "u")$children
    types <- vapply(top, `[[`, "", "type")
    # variables, then the open network settings, then collapsed sections and
    # at most three headings
    expect_identical(types[1:2], c("VariableSupplier", "LayoutBox"), label = a)
    expect_true(all(types[-(1:2)] %in% c("CollapseBox", "Label")), label = a)
    expect_lte(sum(types == "Label"), 3L)
    top_labels <- unlist(lapply(top[[2]]$children, \(col)
      vapply(col$children, `[[`, "", "label")))
    expect_identical(top_labels, c(if (grepl("Cluster", a)) "Clustering", "Network",
                                   "Output", "Reproducibility"),
                     label = paste(a, "top area"))
    boxes <- Filter(\(n) identical(n$type, "CollapseBox"), top)
    expect_false(anyDuplicated(vapply(boxes, `[[`, "", "label")) > 0, label = a)
    invisible(lapply(boxes, \(box) check_box_labels(a, box)))
  }))
})

test_that("long choice lists are drop-downs and sub-options follow their parent", {
  invisible(lapply(ANALYSES, \(a) {
    nodes <- panel_nodes(read_def(a, "u")$children)
    radios <- Filter(\(n) identical(n$type, "RadioButton"), nodes)
    per_option <- table(vapply(radios, `[[`, "", "optionName"))
    expect_true(all(per_option <= 3L), label = paste(a, "radio groups"))
    parents <- Filter(\(n) n$type %in% c("CheckBox", "RadioButton") && length(n$children),
                      nodes)
    invisible(lapply(parents, \(p) lapply(p$children, \(ch)
      expect_match(ch$enable, p$name, fixed = TRUE,
                   label = paste(a, ch$name, "is enabled by", p$name)))))
  }))
})

test_that("results come in the order of the panel", {
  panel_order <- c("buildModelTitle", "clusterTitle", "centralityTitle",
                   "edgeBetweennessTitle", "communityTitle", "cliquesTitle", "backboneTitle",
                   "linksTitle", "rulesTitle", "bootstrapTitle", "stabilityTitle",
                   "permutationTitle", "compareTitle")
  invisible(lapply(ANALYSES, \(a) {
    res <- vapply(read_def(a, "r")$items, `[[`, "", "name")
    headings <- res[res %in% panel_order]
    expect_identical(headings, panel_order[panel_order %in% headings], label = a)
  }))
})

test_that("the panel preview draws every analysis and every section", {
  out <- tempfile(fileext = ".html")
  on.exit(unlink(out), add = TRUE)
  log <- system2(file.path(R.home("bin"), "Rscript"),
                 c(shQuote(file.path(repo_root(), "tools", "preview_panels.R")), shQuote(out)),
                 stdout = TRUE, stderr = TRUE)
  expect_null(attr(log, "status"))
  html <- paste(readLines(out, warn = FALSE, encoding = "UTF-8"), collapse = "\n")
  invisible(lapply(ANALYSES, \(a) {
    expect_match(html, sprintf('id="%s"', a), fixed = TRUE)
    boxes <- Filter(\(n) identical(n$type, "CollapseBox"), read_def(a, "u")$children)
    invisible(lapply(boxes, \(b) expect_match(
      html, sprintf("<summary>%s</summary>", gsub("&", "&amp;", b$label, fixed = TRUE)),
      fixed = TRUE)))
  }))
  # every control type is drawn (an unknown one would print as "[Type name]")
  expect_false(grepl('<div class="ctl">[', html, fixed = TRUE))
  # Seed is greyed until "Set seed" is ticked, as in jamovi
  expect_match(html, 'class="ctl off">Seed', fixed = TRUE)
})
